"""Pure stack-shape helpers for skill digressions.

Frame lists in, frame lists out. Tracker mutation, interrupt events, and
activation stay on ``SkillExecutor``.
"""

from __future__ import annotations

from collections.abc import Sequence
from typing import Optional, TypeGuard

from rasa.dialogue_understanding.stack.frames.dialogue_stack_frame import (
    DialogueStackFrame,
)
from rasa.dialogue_understanding.stack.frames.flow_stack_frame import (
    FlowStackFrameType,
    UserFlowStackFrame,
)
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    MantleStackFrameType,
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.orchestration.skill_utils import (
    lifecycle_skill_id_for_frame,
    owning_skill_id_for_frame,
)
from rasa.mantle.skills.catalog import SkillCatalog

_UserPathFrame = UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame


def park_frame(
    frame: _UserPathFrame,
    park_type: FlowStackFrameType,
) -> _UserPathFrame:
    """Park *frame* as *park_type*, remembering the prior active type.

    When parking an active frame (``REGULAR`` / ``CALL``), store that type in
    ``previous_frame_type``. If the frame is already parked, keep the existing
    ``previous_frame_type`` so re-parking does not lose call-chain identity.
    """
    if isinstance(frame, SkillStackFrame):
        return _park_skill_frame(frame, park_type)
    if isinstance(frame, OrderedBlockStackFrame):
        return _park_block_frame(frame, park_type)
    if frame.frame_type in (
        FlowStackFrameType.INTERRUPT,
        FlowStackFrameType.INLINE_REFERENCE,
    ):
        previous_user_type = frame.previous_frame_type
    else:
        previous_user_type = frame.frame_type
    return UserFlowStackFrame(
        frame_id=frame.frame_id,
        flow_id=frame.flow_id,
        step_id=frame.step_id,
        skill_id=frame.skill_id,
        frame_type=park_type,
        previous_frame_type=previous_user_type,
        suspended_agent_frames=frame.suspended_agent_frames,
    )


def skill_wrapper_below_block(
    frames: Sequence[DialogueStackFrame],
    block_index: int,
) -> Optional[tuple[int, SkillStackFrame]]:
    """Return the skill frame under *block_index*, skipping inline blocks.

    A block switch leaves same-skill ``INLINE_REFERENCE`` blocks between the
    skill frame and the block on top. Those stay inline. Any other frame ends
    the walk, so a different skill is not treated as this block's wrapper.
    """
    if block_index < 0 or block_index >= len(frames):
        return None
    block = frames[block_index]
    if not isinstance(block, OrderedBlockStackFrame):
        return None
    skill_id = block.skill_id
    index = block_index - 1
    while index >= 0:
        frame = frames[index]
        if (
            isinstance(frame, OrderedBlockStackFrame)
            and frame.skill_id == skill_id
            and frame.frame_type == MantleStackFrameType.INLINE_REFERENCE
        ):
            index -= 1
            continue
        if isinstance(frame, SkillStackFrame) and frame.skill_id == skill_id:
            return index, frame
        return None
    return None


def skill_wrapper_below_call_chain(
    frames: Sequence[DialogueStackFrame],
    block_index: int,
) -> Optional[tuple[int, SkillStackFrame]]:
    """Return the skill frame under a called block, skipping its callers.

    :func:`skill_wrapper_below_block` stops at a still-active entry block. A
    same-skill ``call:`` leaves that entry ``REGULAR`` (or ``CALL``, when the
    caller was itself called) under the callee. Those caller frames belong to
    the same run. Any other frame ends the walk.
    """
    if block_index < 0 or block_index >= len(frames):
        return None
    block = frames[block_index]
    if not isinstance(block, OrderedBlockStackFrame):
        return None
    skill_id = block.skill_id
    caller_types = (
        MantleStackFrameType.INLINE_REFERENCE,
        MantleStackFrameType.REGULAR,
        MantleStackFrameType.CALL,
    )
    index = block_index - 1
    while index >= 0:
        frame = frames[index]
        if (
            isinstance(frame, OrderedBlockStackFrame)
            and frame.skill_id == skill_id
            and frame.frame_type in caller_types
        ):
            index -= 1
            continue
        if isinstance(frame, SkillStackFrame) and frame.skill_id == skill_id:
            return index, frame
        return None
    return None


def park_hybrid_skill_wrapper(
    frames: list[DialogueStackFrame],
    interrupted_top: DialogueStackFrame,
) -> None:
    """Park the skill wrapper under an interrupted ordered block.

    Digression only rewrites the top cursor. A hybrid stack is a skill frame
    plus a ``REGULAR`` block. Interrupting the block alone leaves the wrapper
    active (``REGULAR``, or ``CALL`` after ``call:``). Park that wrapper too,
    keeping ``CALL`` in ``previous_frame_type``, so later resume-in-place sees
    one paused family. Same-skill ``INLINE_REFERENCE`` blocks left by a block
    switch sit between the wrapper and the block and are left as they are.
    """
    if not isinstance(interrupted_top, OrderedBlockStackFrame):
        return
    if not frames or not isinstance(frames[-1], OrderedBlockStackFrame):
        return
    under_block = skill_wrapper_below_block(frames, len(frames) - 1)
    if under_block is None:
        return
    index, wrapper = under_block
    if wrapper.frame_type not in (
        MantleStackFrameType.REGULAR,
        MantleStackFrameType.CALL,
    ):
        return
    frames[index] = park_frame(wrapper, FlowStackFrameType.INTERRUPT)


def family_span_bounds(
    frames: Sequence[DialogueStackFrame],
    target_index: int,
) -> tuple[int, int]:
    """Return ``[start, end)`` for the same-skill frames that move together.

    The span walks down through contiguous frames of the target's skill,
    including a skill wrapper and blocks parked as ``INLINE_REFERENCE`` by a
    same-skill block switch. ``activate(skill)`` also includes parked
    ``INTERRUPT`` blocks sitting on that skill. A live ``REGULAR`` block of
    the same skill above the target stays outside the span so resume can
    cancel it. A single prose frame is a span of one.
    """
    target = frames[target_index]
    skill_id = _frame_skill_id(target)
    if skill_id is None:
        return target_index, target_index + 1

    start = target_index
    while start > 0 and _same_skill_span_frame(frames[start - 1], skill_id):
        start -= 1

    end = target_index + 1
    if isinstance(target, SkillStackFrame):
        while end < len(frames) and _parked_same_skill_block(frames[end], skill_id):
            end += 1
    return start, end


def is_parked_frame(frame: DialogueStackFrame) -> bool:
    """Return whether *frame* is a parked digression (``INTERRUPT``)."""
    if isinstance(frame, UserFlowStackFrame):
        return frame.frame_type == FlowStackFrameType.INTERRUPT
    if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
        return frame.frame_type == MantleStackFrameType.INTERRUPT
    return False


def top_live_span_frame_ids(frames: Sequence[DialogueStackFrame]) -> frozenset[str]:
    """Return the ids of the live same-skill frames on top of *frames*.

    Walks down the top same-skill span and stops at the first parked frame, so
    older parked frames of that skill under a newly activated block are left
    out. A parked top frame yields an empty set.
    """
    if not frames:
        return frozenset()
    start, end = family_span_bounds(frames, len(frames) - 1)
    live_ids: set[str] = set()
    for frame in reversed(frames[start:end]):
        if is_parked_frame(frame):
            break
        live_ids.add(frame.frame_id)
    return frozenset(live_ids)


def span_is_live(
    frames: Sequence[DialogueStackFrame], frame_ids: frozenset[str]
) -> bool:
    """Return whether *frame_ids* are on *frames* with nothing parked at or above.

    Parking marks only the top frame ``INTERRUPT`` (for an ordered-block skill,
    the block above a still-``REGULAR`` skill frame; for a ``call:``, the
    callee above a still-``REGULAR`` caller). A parked frame at or above the
    span's lowest frame therefore means the span is not the one in progress.
    """
    lowest = next(
        (index for index, frame in enumerate(frames) if frame.frame_id in frame_ids),
        None,
    )
    if lowest is None:
        return False
    return not any(is_parked_frame(frame) for frame in frames[lowest:])


def interrupted_skill_wrapper_below_block(
    frames: Sequence[DialogueStackFrame],
) -> Optional[tuple[int, SkillStackFrame]]:
    """Return the skill frame under the block on top of *frames*."""
    if not frames:
        return None
    return skill_wrapper_below_block(frames, len(frames) - 1)


def resume_block_above_inline_span(
    frames: Sequence[DialogueStackFrame],
    skill_index: int,
) -> Optional[int]:
    """Return the parked block above a skill when only inline blocks sit between.

    ``activate(skill)`` then resumes that block, same as ``activate(block)``.
    A lone inline block above the skill, or an adjacent parked block with no
    inline frame between, returns ``None`` so the skill index stays the target.
    """
    if skill_index < 0 or skill_index >= len(frames):
        return None
    skill = frames[skill_index]
    if not isinstance(skill, SkillStackFrame):
        return None
    skill_id = skill.skill_id
    index = skill_index + 1
    if index >= len(frames) or not _same_skill_inline_block(frames[index], skill_id):
        return None
    while index < len(frames) and _same_skill_inline_block(frames[index], skill_id):
        index += 1
    if index >= len(frames) or not _parked_same_skill_block(frames[index], skill_id):
        return None
    while index + 1 < len(frames) and _parked_same_skill_block(
        frames[index + 1], skill_id
    ):
        index += 1
    return index


def span_owner_skill_id(
    catalog: SkillCatalog,
    span: Sequence[DialogueStackFrame],
) -> Optional[str]:
    """Return the skill that owns the resumed span, if it has one."""
    if not span:
        return None
    owner = span[0]
    if not isinstance(
        owner, (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame)
    ):
        return None
    return owning_skill_id_for_frame(catalog, owner)


def rehome_frames_above_resume_target(
    above: list[DialogueStackFrame],
    *,
    catalog: SkillCatalog,
    target_skill_id: Optional[str],
) -> tuple[list[_UserPathFrame], list[_UserPathFrame], bool]:
    """Cancel prompts and same-skill cursors; park every other live skill.

    Mutates *above* in place. Walks from the top so a hybrid block is parked
    together with the skill frame under it. A half-parked wrapper (skill still
    ``REGULAR`` under an ``INTERRUPT`` block) is parked without appearing in
    the interrupt list — the block was already interrupted.

    Returns frames to cancel, live frames that were just parked (so the caller
    can emit interrupt events), and whether any live skill was parked.
    """
    frames_to_cancel: list[_UserPathFrame] = []
    frames_to_interrupt: list[_UserPathFrame] = []
    parked = False
    index = len(above) - 1
    while index >= 0:
        frame = above[index]
        if not isinstance(
            frame, (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame)
        ):
            index -= 1
            continue
        if _should_cancel_frame_above_resume_target(catalog, frame, target_skill_id):
            frames_to_cancel.append(frame)
            del above[index]
            index -= 1
            continue
        if _plain_regular_user_digression_frame(frame):
            frames_to_interrupt.append(frame)
            above[index] = park_frame(frame, FlowStackFrameType.INTERRUPT)
            if isinstance(frame, OrderedBlockStackFrame):
                parked = _park_regular_wrapper_under_block(above, index) or parked
            parked = True
            index -= 1
            continue
        if isinstance(frame, OrderedBlockStackFrame):
            parked = _park_regular_wrapper_under_block(above, index) or parked
        index -= 1
    return frames_to_cancel, frames_to_interrupt, parked


def _park_skill_frame(
    frame: SkillStackFrame,
    park_type: FlowStackFrameType,
) -> SkillStackFrame:
    parked_type = MantleStackFrameType.from_str(park_type.value)
    if frame.frame_type in (
        MantleStackFrameType.INTERRUPT,
        MantleStackFrameType.INLINE_REFERENCE,
    ):
        previous = frame.previous_frame_type
    else:
        previous = frame.frame_type
    return SkillStackFrame(
        frame_id=frame.frame_id,
        skill_id=frame.skill_id,
        frame_type=parked_type,
        previous_frame_type=previous,
    )


def _park_block_frame(
    frame: OrderedBlockStackFrame,
    park_type: FlowStackFrameType,
) -> OrderedBlockStackFrame:
    parked_block_type = MantleStackFrameType.from_str(park_type.value)
    if frame.frame_type in (
        MantleStackFrameType.INTERRUPT,
        MantleStackFrameType.INLINE_REFERENCE,
    ):
        previous_block_type = frame.previous_frame_type
    else:
        previous_block_type = frame.frame_type
    return OrderedBlockStackFrame(
        frame_id=frame.frame_id,
        skill_id=frame.skill_id,
        block_id=frame.block_id,
        step_id=frame.step_id,
        frame_type=parked_block_type,
        previous_frame_type=previous_block_type,
    )


def _should_cancel_frame_above_resume_target(
    catalog: SkillCatalog,
    frame: _UserPathFrame,
    target_skill_id: Optional[str],
) -> bool:
    """Return whether *frame* is a prompt or a cursor of the resumed skill.

    Lifecycle defaults are removed. A ``REGULAR`` frame of the skill being
    resumed is removed so that skill's own block is not parked under its
    wrapper. Another skill's live frame is parked instead.
    """
    if not _plain_regular_user_digression_frame(frame):
        return False
    if lifecycle_skill_id_for_frame(catalog, frame) is not None:
        return True
    if target_skill_id is None:
        return False
    return owning_skill_id_for_frame(catalog, frame) == target_skill_id


def _park_regular_wrapper_under_block(
    frames: list[DialogueStackFrame],
    block_index: int,
) -> bool:
    """Park a ``REGULAR`` skill frame under a block, skipping inline blocks.

    Returns whether a wrapper was parked. ``CALL`` and inline wrappers are
    left alone; resume-in-place does not run when those sit above the target.
    """
    under_block = skill_wrapper_below_block(frames, block_index)
    if under_block is None:
        return False
    index, wrapper = under_block
    if wrapper.frame_type != MantleStackFrameType.REGULAR:
        return False
    if wrapper.previous_frame_type in (
        MantleStackFrameType.CALL,
        MantleStackFrameType.INLINE_REFERENCE,
    ):
        return False
    frames[index] = park_frame(wrapper, FlowStackFrameType.INTERRUPT)
    return True


def _plain_regular_user_digression_frame(
    frame: DialogueStackFrame,
) -> TypeGuard[_UserPathFrame]:
    """Return whether *frame* is an ordinary active user task on the stack.

    "Plain" means a normal ``REGULAR`` skill, block, or user-flow cursor —
    the task currently in progress — as opposed to structural frames
    (``CALL``, ``INLINE_REFERENCE``, ``LINK``) or a parked ``INTERRUPT``
    sibling.
    """
    if isinstance(frame, UserFlowStackFrame):
        return frame.frame_type == FlowStackFrameType.REGULAR
    if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
        return frame.frame_type == MantleStackFrameType.REGULAR
    return False


def _frame_skill_id(frame: DialogueStackFrame) -> Optional[str]:
    """Return the skill id for a skill or block frame."""
    if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
        return frame.skill_id or None
    return None


def _same_skill_span_frame(frame: DialogueStackFrame, skill_id: str) -> bool:
    """Return whether *frame* belongs to the resumed skill's contiguous span."""
    if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
        return frame.skill_id == skill_id
    return False


def resume_in_place_tool_result(
    flow_id: str,
    *,
    parked_live_skill: bool,
    cancelled_user_digression: bool,
    kept_paused_task: bool,
) -> str:
    """Return the tool result after a resume-in-place.

    A live skill that was just parked is still in progress. A cancelled
    non-lifecycle frame was a digression the user dropped. Removing only a
    lifecycle prompt leaves other paused tasks on the stack.
    """
    if parked_live_skill:
        return f"Resumed '{flow_id}'; the task in progress was paused."
    if cancelled_user_digression:
        return f"Resumed '{flow_id}'; the previous digression was abandoned."
    if kept_paused_task:
        return f"Resumed '{flow_id}'; other paused tasks were kept."
    return f"Resumed '{flow_id}'."


def _same_skill_inline_block(frame: DialogueStackFrame, skill_id: str) -> bool:
    """Return whether *frame* is a same-skill block parked by a block switch."""
    return (
        isinstance(frame, OrderedBlockStackFrame)
        and frame.skill_id == skill_id
        and frame.frame_type == MantleStackFrameType.INLINE_REFERENCE
    )


def _parked_same_skill_block(frame: DialogueStackFrame, skill_id: str) -> bool:
    """Return whether *frame* is a parked block of *skill_id*."""
    if not isinstance(frame, OrderedBlockStackFrame):
        return False
    if frame.skill_id != skill_id:
        return False
    if frame.frame_type != MantleStackFrameType.INTERRUPT:
        return False
    return frame.previous_frame_type not in (
        MantleStackFrameType.CALL,
        MantleStackFrameType.INLINE_REFERENCE,
    )
